function ext(raw:string){const m=raw.match(/^---\r?\n[\s\S]*?\r?\n---\r?\n/);return {meta:m?.[0]||'',body:raw.slice(m?.[0].length||0)};}
function stamp(iso:string){return iso?new Date(iso).toLocaleDateString('vi-VN'):'';}
const low=(s:string)=>s.toLocaleLowerCase('vi');
const hasText=(hay:string,needle:string)=>!needle||low(hay).includes(low(needle));
