  <header className="topbar"><button className="mobile-menu icon" aria-label="Đóng hoặc mở thư viện" aria-expanded={mobileNav} onClick={toggleLibrary}><Menu size={20}/></button><div className="brand-side"><Link href="/" className="brand"><span className="brand-mark"><BookOpen size={21}/></span><span className="brand-copy"><strong>ATLAS DOCS</strong><small>by Ezway Tech</small></span></Link><div className="top-promo"><Tooltip content="Mã nguồn trên GitHub"><a href={PRODUCT_GITHUB} target="_blank" rel="noreferrer" aria-label="GitHub"><GithubMark/><span>GitHub</span></a></Tooltip><Tooltip content="Trang chủ Ezway Tech"><a href={PRODUCT_HOME} target="_blank" rel="noreferrer" aria-label="Trang chủ Ezway Tech"><Globe size={16}/><span>Ezway</span></a></Tooltip></div></div><button className="top-search" onClick={()=>folderSearch(null)}><Search size={17}/> Tìm kiếm tài liệu... <kbd>Ctrl K</kbd></button><div className="top-actions"><button onClick={()=>setDialog('backup')}><Archive size={18}/> <span>Backup</span></button><Tooltip content="Thư viện ảnh"><button aria-label="Thư viện ảnh" onClick={()=>openMedia('insert')}><ImageIcon size={18}/></button></Tooltip><Tooltip content={dark?'Giao diện sáng':'Giao diện tối'}><button aria-label={dark?'Giao diện sáng':'Giao diện tối'} onClick={toggleTheme}>{dark?<Sun size={18}/>:<Moon size={18}/>}</button></Tooltip></div></header>
